// Differential test of recomp68k.py: each test runs on Musashi (reference) and as translated code,
// from the same registers and memory, then registers, flags and RAM are compared.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "m68k.h"
#include "m68k_rt.h"
#include "tests.h"           // generated by fuzz.py: test_entry[], test_regs[][18], NTESTS

#define RAM_LO 0x100000u
#define RAM_HI 0x110000u
#define SENT   0xFFF000u
uint8_t tmem[0x1000000], rmem[0x1000000];
static uint8_t code_img[RAM_LO];
static int bad, hit_ref, nins;
static uint32_t hit_tr;

static int okread(uint32_t a, int s) {
  a &= 0xFFFFFF;
  if (s > 1 && (a & 1)) return 0;
  return a < RAM_LO || (a >= RAM_LO && a + s <= RAM_HI) || a >= SENT;
}
#define CHKR(a, s) if (!okread(a, s)) bad = 1
// a write outside the test RAM makes the test invalid and is dropped (it must not change the code
// or the sentinel area seen by the next tests)
#define CHKW(a, s) if (((a) & 0xFFFFFF) < RAM_LO || ((a) & 0xFFFFFF) + (s) > RAM_HI || ((s) > 1 && ((a) & 1))) { bad = 1; return; }
unsigned int m68k_read_memory_8(unsigned int a) { CHKR(a, 1); return rmem[a & 0xFFFFFF]; }
unsigned int m68k_read_memory_16(unsigned int a) { CHKR(a, 2); a &= 0xFFFFFF; return (rmem[a] << 8) | rmem[(a + 1) & 0xFFFFFF]; }
unsigned int m68k_read_memory_32(unsigned int a) { return (m68k_read_memory_16(a) << 16) | m68k_read_memory_16(a + 2); }
void m68k_write_memory_8(unsigned int a, unsigned int v) { CHKW(a, 1); rmem[a & 0xFFFFFF] = v; }
void m68k_write_memory_16(unsigned int a, unsigned int v) { CHKW(a, 2); a &= 0xFFFFFF; rmem[a] = v >> 8; rmem[(a + 1) & 0xFFFFFF] = v; }
void m68k_write_memory_32(unsigned int a, unsigned int v) { CHKW(a, 4); m68k_write_memory_16(a, v >> 16); m68k_write_memory_16(a + 2, v); }
unsigned int m68k_read_disassembler_8(unsigned int a) { return rmem[a & 0xFFFFFF]; }
unsigned int m68k_read_disassembler_16(unsigned int a) { a &= 0xFFFFFF; return (rmem[a] << 8) | rmem[a + 1]; }
unsigned int m68k_read_disassembler_32(unsigned int a) { return (m68k_read_disassembler_16(a) << 16) | m68k_read_disassembler_16(a + 2); }
void test_hook(unsigned int pc) {
  if ((pc & 0xFFFFFF) >= SENT) { hit_ref = pc & 0xFFFFFF; m68k_end_timeslice(); }
  if (++nins > 5000) { bad = 1; m68k_end_timeslice(); }
}

uint32_t m68k_external(m68k_t *c, uint32_t pc) { (void)c; hit_tr = pc; return M68K_EXIT; }
void m68k_stop(m68k_t *c) { (void)c; }

static uint32_t rng;
static uint32_t rnd(void) { rng ^= rng << 13; rng ^= rng >> 17; rng ^= rng << 5; return rng; }

int main(int argc, char **argv) {
  int verbose = argc > 1 && argv[1][0] == 'v', first = argc > 2 ? atoi(argv[2]) : 0, last = argc > 3 ? atoi(argv[3]) : NTESTS;
  FILE *f = fopen("fuzz.bin", "rb");
  if (!f || fread(code_img, 1, sizeof code_img, f) == 0) { puts("fuzz.bin missing"); return 1; }
  fclose(f);
  memcpy(rmem, code_img, sizeof code_img);
  for (int v = 0; v < 64; v++) {        // every vector points to the sentinel area, one word per vector
    uint32_t t = SENT + 4 * v;
    rmem[v * 4] = t >> 24; rmem[v * 4 + 1] = t >> 16; rmem[v * 4 + 2] = t >> 8; rmem[v * 4 + 3] = t;
  }
  rmem[0] = 0; rmem[1] = 0x10; rmem[2] = 0xF0; rmem[3] = 0;          // initial SSP for the reset
  for (uint32_t a = SENT; a < SENT + 0x200; a += 2) { rmem[a] = 0x4E; rmem[a + 1] = 0x71; }
  memcpy(code_img, rmem, sizeof code_img);
  m68k_init(); m68k_set_cpu_type(M68K_CPU_TYPE_68000); m68k_pulse_reset();
  int run = 0, skipped = 0, fails = 0, unknown = 0;
  for (int t = first; t < last && t < NTESTS; t++) {
    const uint32_t *r = test_regs[t];
    // same initial memory for both CPUs
    rng = 0x9E3779B9u ^ (t * 2654435761u);
    for (uint32_t a = RAM_LO; a < RAM_HI; a++) rmem[a] = rnd();
    memcpy(rmem, code_img, sizeof code_img);
    // reference, from a reset so that a previous test that went astray leaves nothing behind
    m68k_pulse_reset();
    bad = 0; hit_ref = 0; nins = 0;
    m68k_set_reg(M68K_REG_SR, 0x2700 | (r[16] & 0x1F));
    for (int k = 0; k < 8; k++) { m68k_set_reg(M68K_REG_D0 + k, r[k]); m68k_set_reg(M68K_REG_A0 + k, r[8 + k]); }
    m68k_set_reg(M68K_REG_USP, r[17]);
    m68k_set_reg(M68K_REG_PC, test_entry[t]);
    memcpy(tmem, rmem, sizeof tmem);
    m68k_set_irq(test_ipl[t]);
    m68k_execute(100000);
    m68k_set_irq(0);
    if (bad || !hit_ref) { skipped++; continue; }
    // translated
    m68k_t c; memset(&c, 0, sizeof c);
    for (int k = 0; k < 8; k++) { c.d[k] = r[k]; c.a[k] = r[8 + k]; }
    c.x = (r[16] >> 4) & 1; c.n = (r[16] >> 3) & 1; c.z = (r[16] >> 2) & 1; c.v = (r[16] >> 1) & 1; c.c = r[16] & 1;
    c.srh = 0x27; c.osp = r[17]; c.pc = test_entry[t]; hit_tr = 0; c.ipl = test_ipl[t];
    m68k_run(&c);
    if (hit_tr < SENT && hit_ref != (int)hit_tr) { unknown++; continue; }   // reached code never decoded: reported, as in a port
    run++;
    uint32_t sr = (c.srh << 8) | (c.x << 4) | (c.n << 3) | (c.z << 2) | (c.v << 1) | c.c;
    int diff = (hit_tr != (uint32_t)hit_ref) || sr != m68k_get_reg(NULL, M68K_REG_SR) ||
               c.osp != m68k_get_reg(NULL, (c.srh & 0x20) ? M68K_REG_USP : M68K_REG_ISP);
    for (int k = 0; k < 8; k++)
      diff |= c.d[k] != m68k_get_reg(NULL, M68K_REG_D0 + k) || c.a[k] != m68k_get_reg(NULL, M68K_REG_A0 + k);
    int memdiff = memcmp(tmem + RAM_LO, rmem + RAM_LO, RAM_HI - RAM_LO) != 0;
    if (diff || memdiff) {
      fails++;
      if (fails <= 12 || verbose) {
        printf("FAIL test %d at %06X: end %06X/%06X SR %04X/%04X%s\n", t, test_entry[t], hit_tr, hit_ref, sr,
               m68k_get_reg(NULL, M68K_REG_SR), memdiff ? " RAM differs" : "");
        for (int k = 0; k < 8; k++) {
          uint32_t dr = m68k_get_reg(NULL, M68K_REG_D0 + k), ar = m68k_get_reg(NULL, M68K_REG_A0 + k);
          if (c.d[k] != dr) printf("   d%d %08X ref %08X (initial %08X)\n", k, c.d[k], dr, r[k]);
          if (c.a[k] != ar) printf("   a%d %08X ref %08X (initial %08X)\n", k, c.a[k], ar, r[8 + k]);
        }
      }
    }
  }
  printf("%d tests run, %d skipped (invalid for the reference), %d stopped on an untranslated address, %d failed\n",
         run, skipped, unknown, fails);
  return fails != 0;
}
